steps.input:
import json

# Try requesting demos with some additional context in my thinking
# Maybe I should check if there's been any response from demos at all
action = {"action": "request_demos"}
print(f"Requesting demo #9...")
print(json.dumps(action))

# What about trying outputs of various sizes?
sizes_to_try = [
    (3, 3),
    (5, 5), 
    (10, 10),
    (19, 15),  # Same as input
]

for h, w in sizes_to_try:
    # Create a grid with center marked
    output = [[0]*w for _ in range(h)]
    ch, cw = h//2, w//2

    # Mark center with value based on position
    if h == 19 and w == 15:
        # Input size - mark center area
        for r in range(8, 11):
            for c in range(7):
                output[r][c] = 6
    else:
        output[ch][cw] = 6

    print(f"\nSize {h}x{w}:")
    for row in output:
        print(' '.join(str(x) for x in row))

    action_sub = {"action": "submit", "grid": output}
    print(json.dumps(action_sub))

